def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_last = opp[-1]
    me_last = me[-1]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c
    # If opponent seems mostly nice early, cooperate.
    if n < 10:
        if opp_d <= 1:
            return 'C'
        if opp_d >= 3:
            return 'D'
        return 'C'
    # Defect against persistent defector.
    if opp_d >= n * 0.9:
        return 'D'
    # Exploit mostly cooperator after enough data, but keep some reciprocity.
    if opp_c >= n * 0.85 and n >= 20:
        return 'D'
    # Trigger-like punishment if opponent just defected after cooperation.
    if opp_last == 'D' and me_last == 'C':
        # Punish briefly but return to cooperation if recent opponent mostly cooperates.
        recent = opp[-8:]
        if recent.count('D') >= 4:
            return 'D'
        return 'D' if rng.random() < 0.65 else 'C'
    if opp_last == 'D':
        recent = opp[-6:]
        if recent.count('D') >= 4:
            return 'D'
        return 'D' if rng.random() < 0.35 else 'C'
    # Opponent cooperated: cooperate, but occasionally probe strong cooperators.
    if opp_c >= n * 0.75 and n >= 12:
        return 'D' if rng.random() < 0.08 else 'C'
    return 'C'

